import{_ as e,o as t,c as n,ae as a}from"./chunks/framework.Dzr56EFm.js";const u=JSON.parse('{"title":"设计趋势 - 2026-07-04","description":"","frontmatter":{"date":"2026-07-04T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-07-04-uxtrend.md","filePath":"daily/2026-07-04-uxtrend.md"}'),o={name:"daily/2026-07-04-uxtrend.md"};function s(i,r,g,p,l,h){return t(),n("div",null,[...r[0]||(r[0]=[a('<h1 id="设计趋势-2026-07-04" tabindex="-1">设计趋势 - 2026-07-04 <a class="header-anchor" href="#设计趋势-2026-07-04" aria-label="Permalink to &quot;设计趋势 - 2026-07-04&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于代理型用户体验（代理UX）和AI在设计中的应用。代理UX强调人机信任构建，而非仅界面和功能，提出了设计代理系统的7个原则，以增强上下文的双向流动和信任感。AI的应用正在改变设计工作流程，提升创意工作的适应性和团队协作。最值得关注的是代理UX设计原则和AI在设计中的深度整合。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 设计原则助力数字设备中的新型用户体验</p><p><strong>能解决什么问题</strong>: 解决数字设备中代理系统用户体验设计问题</p><p><strong>产品应用</strong>: 适用于数字设备，通过AI提升人机协作效率</p><p><strong>示例场景</strong>: 智能助手协助用户进行日常任务规划</p><hr><h3 id="_2-为什么代理型ux将改变你对设计的了解" tabindex="-1">2. 为什么代理型UX将改变你对设计的了解 <a class="header-anchor" href="#_2-为什么代理型ux将改变你对设计的了解" aria-label="Permalink to &quot;2. 为什么代理型UX将改变你对设计的了解&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/generative-ai-revolution-ai-native-transformation/why-agentic-ux-will-change-everything-you-know-about-design-0394486f5add" target="_blank" rel="noreferrer">Why Agentic UX Will Change Everything You Know About Design</a></p><p><strong>一句话摘要</strong>: 代理型UX设计关注人机信任的构建，而非界面和功能。</p><p><strong>能解决什么问题</strong>: 如何让用户信任并有效利用AI代理，而不感到被控制。</p><p><strong>产品应用</strong>: 适用于需要人机协作的智能系统，通过设计提升用户信任和控制感。</p><p><strong>示例场景</strong>: 金融系统中AI代理提示可疑交易但需人工确认。</p><hr><h3 id="_3-代理式用户体验-设计代理系统的7个原则" tabindex="-1">3. 代理式用户体验：设计代理系统的7个原则 <a class="header-anchor" href="#_3-代理式用户体验-设计代理系统的7个原则" aria-label="Permalink to &quot;3. 代理式用户体验：设计代理系统的7个原则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/agentic-ux-7-principles-for-designing-systems-with-agents-019512c2caa9" target="_blank" rel="noreferrer">Agentic UX: 7 principles for designing systems with agents</a></p><p><strong>一句话摘要</strong>: 设计代理系统时应考虑上下文的双向流动，以增强信任感。</p><p><strong>能解决什么问题</strong>: 解决代理系统与用户交互时的上下文断层和信任问题。</p><p><strong>产品应用</strong>: 适用于需要智能代理辅助的任何产品，如客服机器人。</p><p><strong>示例场景</strong>: 智能客服在用户浏览商品时提供个性化推荐。</p><hr><h3 id="_4-ai在设计中的应用-改变创造方式" tabindex="-1">4. AI在设计中的应用：改变创造方式 <a class="header-anchor" href="#_4-ai在设计中的应用-改变创造方式" aria-label="Permalink to &quot;4. AI在设计中的应用：改变创造方式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/ai-in-design" target="_blank" rel="noreferrer">AI in Design: Transforming the Way We Create - Figma</a></p><p><strong>一句话摘要</strong>: AI将深度整合进设计工作流程，提升创意工作的适应性和团队协作。</p><p><strong>能解决什么问题</strong>: 解决设计任务自动化和个性化界面创建的问题。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI提升设计效率和用户体验。</p><p><strong>示例场景</strong>: 设计师利用AI快速生成多个设计选项，选择最佳方案进行细化。</p><hr><h3 id="_5-ai交互模式-让用户识别和与ai驱动功能互动" tabindex="-1">5. AI交互模式：让用户识别和与AI驱动功能互动 <a class="header-anchor" href="#_5-ai交互模式-让用户识别和与ai驱动功能互动" aria-label="Permalink to &quot;5. AI交互模式：让用户识别和与AI驱动功能互动&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@flik185/ai-interaction-patterns-giving-users-ways-to-recognize-and-interact-with-ai-driven-features-22055a91206b" target="_blank" rel="noreferrer">AI Interaction Patterns: Giving Users Ways to Recognize and Interact With Ai-Driven Features</a></p><p><strong>一句话摘要</strong>: 通过交互模式建立人与AI之间的信任关系</p><p><strong>能解决什么问题</strong>: 如何让用户识别并有效与AI功能互动</p><p><strong>产品应用</strong>: 适用于AI工具，如聊天机器人、分析仪表板等</p><p><strong>示例场景</strong>: 聊天机器人中提供调整响应方式的选项</p><hr><h3 id="_6-ai-ux设计模式-人工智能带来的新体验" tabindex="-1">6. AI UX设计模式：人工智能带来的新体验 <a class="header-anchor" href="#_6-ai-ux设计模式-人工智能带来的新体验" aria-label="Permalink to &quot;6. AI UX设计模式：人工智能带来的新体验&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://lukelance.medium.com/ai-ux-design-patterns-53d9e378f808" target="_blank" rel="noreferrer">AI UX Design Patterns. Artificial Intelligence brings a new… | by Luke Bennis | Medium</a></p><p><strong>一句话摘要</strong>: AI UX设计模式为AI产品提供关键交互模式参考。</p><p><strong>能解决什么问题</strong>: 帮助设计师在AI产品中做出更好的用户体验决策。</p><p><strong>产品应用</strong>: 可以应用到AI产品中，通过评估选择适合的交互模式。</p><p><strong>示例场景</strong>: 设计一个使用AI的智能助手时，选择合适的交互模式。</p><hr><h3 id="_7-在cursor中使用ai可读设计系统进行设计" tabindex="-1">7. 在Cursor中使用AI可读设计系统进行设计 <a class="header-anchor" href="#_7-在cursor中使用ai可读设计系统进行设计" aria-label="Permalink to &quot;7. 在Cursor中使用AI可读设计系统进行设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/working-with-ai-readable-design-systems-in-cursor-2bba9c9c09d9" target="_blank" rel="noreferrer">Designing with AI-readable design systems in Cursor</a></p><p><strong>一句话摘要</strong>: AI直接将产品需求和UX规范转化为完整产品流程。</p><p><strong>能解决什么问题</strong>: 提高设计效率，确保设计遵循统一的设计系统。</p><p><strong>产品应用</strong>: 适用于需要快速原型制作的产品设计流程，确保设计一致性。</p><p><strong>示例场景</strong>: 设计师使用产品需求生成符合设计系统的原型。</p><hr><h3 id="_8-设计代理型用户体验指南" tabindex="-1">8. 设计代理型用户体验指南 <a class="header-anchor" href="#_8-设计代理型用户体验指南" aria-label="Permalink to &quot;8. 设计代理型用户体验指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ai-ux-designers/era-of-agentive-ux-not-agentic-64dd765a0372" target="_blank" rel="noreferrer">Designing for Agentive UX — A Guide</a></p><p><strong>一句话摘要</strong>: 从设计直观控制转向设计能够预测用户未知需求的代理。</p><p><strong>能解决什么问题</strong>: 如何设计能够预测并满足用户未来需求的智能代理。</p><p><strong>产品应用</strong>: 可以应用到智能助手、推荐系统等产品中，通过分析用户数据预测需求。</p><p><strong>示例场景</strong>: 智能助手根据用户习惯自动推荐可能感兴趣的新闻。</p><hr><h3 id="_9-cursor与vercel-ux设计师对网站构建未来的真实看法" tabindex="-1">9. Cursor与Vercel：UX设计师对网站构建未来的真实看法 <a class="header-anchor" href="#_9-cursor与vercel-ux设计师对网站构建未来的真实看法" aria-label="Permalink to &quot;9. Cursor与Vercel：UX设计师对网站构建未来的真实看法&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://jennygenerate.medium.com/cursor-vs-vercel-a-ux-designers-honest-take-on-the-future-of-website-building-5faf8bf88a9c" target="_blank" rel="noreferrer">Cursor vs Vercel: A UX Designer’s Honest Take on the Future of Website Building | by Jennygenerate | Medium</a></p><p><strong>一句话摘要</strong>: AI工具Cursor和Vercel正在改变网站设计和构建方式。</p><p><strong>能解决什么问题</strong>: 简化网站开发流程，加速部署，让设计师更专注于创意。</p><p><strong>产品应用</strong>: 适用于需要快速原型和布局设计的项目，减少手动编码工作。</p><p><strong>示例场景</strong>: 设计师使用Cursor快速生成网站布局，提升工作效率。</p><hr><h3 id="_10-构建信任与增强交互-7个关键的ai-ux模式" tabindex="-1">10. 构建信任与增强交互：7个关键的AI UX模式 <a class="header-anchor" href="#_10-构建信任与增强交互-7个关键的ai-ux模式" aria-label="Permalink to &quot;10. 构建信任与增强交互：7个关键的AI UX模式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/bestfolios/building-trust-and-enhancing-interactions-7-essential-ai-ux-patterns-in-action-12e7604de435" target="_blank" rel="noreferrer">Building Trust and Enhancing Interactions: 7 Essential AI UX Patterns in Action</a></p><p><strong>一句话摘要</strong>: 通过上下文提及和智能代码块等模式，提升AI交互的效率和用户体验。</p><p><strong>能解决什么问题</strong>: 提高AI工具的可用性和用户信任度，优化开发和交互流程。</p><p><strong>产品应用</strong>: 适用于编码助手和企业工具，通过嵌入动作提升代码片段的交互性。</p><p><strong>示例场景</strong>: ChatGPT通过智能代码块提供代码片段和操作按钮，提升开发效率。</p><hr>',75)])])}const c=e(o,[["render",s]]);export{u as __pageData,c as default};
